import{_ as t,a0 as o,w as r,s as d,ao as l,I as e,x as a,a1 as i,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"如何管理你的 Linux 環境變量 | LCTT x X-CMD","titleTemplate":false,"description":"如何管理你的 Linux 環境變量 | LCTT (201905) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何管理你的 Linux 環境變量 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何管理你的 Linux 環境變量 | LCTT (201905) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201905/20190329 How to manage your Linux environment","title":"如何管理你的 Linux 環境變量","tag":"201905","desc":""},"relativePath":"201905/20190329 How to manage your Linux environment.md","filePath":"[post].md"}'),h={name:"201905/20190329 How to manage your Linux environment.md"};function g(c,s,u,b,k,m){const n=o("Link");return r(),d("div",null,[s[24]||(s[24]=l(`<h1 id="如何管理你的-linux-環境變量" tabindex="-1">如何管理你的 Linux 環境變量 <a class="header-anchor" href="#如何管理你的-linux-環境變量" aria-label="Permalink to “如何管理你的 Linux 環境變量”">​</a></h1><blockquote><p>Linux 用户環境變量可以幫助你找到你需要的命令，無須瞭解系統如何配置的細節而完成大量工作。而這些設置來自哪裏和如何被修改它們是另一個話題。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2019/03/environment-rocks-leaves-100792229-large.jpg" alt="IIP Photo Archive CC BY 2.0"></p><p>在 Linux 系統上的用户賬户配置以多種方法簡化了系統的使用。你可以運行命令，而不需要知道它們的位置。你可以重新使用先前運行的命令，而不用發愁系統是如何追蹤到它們的。你可以查看你的電子郵件，查看手冊頁，並容易地回到你的家目錄，而不用管你在文件系統中身在何方。並且，當需要的時候，你可以調整你的賬户設置，以便其更符合你喜歡的方式。</p><p>Linux 環境設置來自一系列的文件：一些是系統範圍（意味着它們影響所有用户賬户），一些是處於你的家目錄中的配置文件裏。系統範圍的設置在你登錄時生效，而本地設置在其後生效，所以，你在你賬户中作出的更改將覆蓋系統範圍設置。對於 bash 用户，這些文件包含這些系統文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/etc/environment</span></span>
<span class="line"><span>/etc/bash.bashrc</span></span>
<span class="line"><span>/etc/profile</span></span></code></pre></div><p>以及一些本地文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~/.bashrc</span></span>
<span class="line"><span>~/.profile # 如果有 ~/.bash_profile 或 ~/.bash_login 就不會讀此文件</span></span>
<span class="line"><span>~/.bash_profile</span></span>
<span class="line"><span>~/.bash_login</span></span></code></pre></div><p>你可以修改本地存在的四個文件的任何一個，因為它們處於你的家目錄，並且它們是屬於你的。</p><h3 id="查看你的-linux-環境設置" tabindex="-1">查看你的 Linux 環境設置 <a class="header-anchor" href="#查看你的-linux-環境設置" aria-label="Permalink to “查看你的 Linux 環境設置”">​</a></h3><p>為查看你的環境設置，使用 <code>env</code> 命令。你的輸出將可能與這相似：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ env</span></span>
<span class="line"><span>LS_COLORS=rs=0:di=01;34:ln=01;36:mh=00:pi=40;33:so=01;35:do=01;35:bd=40;33;01:cd=40;33;</span></span>
<span class="line"><span>01:or=40;31;01:mi=00:su=37;41:sg=30;43:ca=30;41:tw=30;42:ow=34;42:st=37;44:ex=01;32:</span></span>
<span class="line"><span>*.tar=01;31:*.tgz=01;31:*.arc=01;31:*.arj=01;31:*.taz=01;31:*.lha=01;31:*.lz4=01;31:</span></span>
<span class="line"><span>*.lzh=01;31:*.lzma=01;31:*.tlz=01;31:*.txz=01;31:*.tzo=01;31:*.t7z=01;31:*.zip=01;31:</span></span>
<span class="line"><span>*.z=01;31:*.Z=01;31:*.dz=01;31:*.gz=01;31:*.lrz=01;31:*.lz=01;31:*.lzo=01;31:*.xz=01;</span></span>
<span class="line"><span>31:*.zst=01;31:*.tzst=01;31:*.bz2=01;31:*.bz=01;31:*.tbz=01;31:*.tbz2=01;31:*.tz=01;31:</span></span>
<span class="line"><span>*.deb=01;31:*.rpm=01;31:*.jar=01;31:*.war=01;31:*.ear=01;31:*.sar=01;31:*.rar=01;31:</span></span>
<span class="line"><span>*.alz=01;31:*.ace=01;31:*.zoo=01;31:*.cpio=01;31:*.7z=01;31:*.rz=01;31:*.cab=01;31:</span></span>
<span class="line"><span>*.wim=01;31:*.swm=01;31:*.dwm=01;31:*.esd=01;31:*.jpg=01;35:*.jpeg=01;35:*.mjpg=01;35:</span></span>
<span class="line"><span>*.mjpeg=01;35:*.gif=01;35:*.bmp=01;35:*.pbm=01;35:*.pgm=01;35:*.ppm=01;35:*.tga=01;35:</span></span>
<span class="line"><span>*.xbm=01;35:*.xpm=01;35:*.tif=01;35:*.tiff=01;35:*.png=01;35:*.svg=01;35:*.svgz=01;35:</span></span>
<span class="line"><span>*.mng=01;35:*.pcx=01;35:*.mov=01;35:*.mpg=01;35:*.mpeg=01;35:*.m2v=01;35:*.mkv=01;35:</span></span>
<span class="line"><span>*.webm=01;35:*.ogm=01;35:*.mp4=01;35:*.m4v=01;35:*.mp4v=01;35:*.vob=01;35:*.qt=01;35:</span></span>
<span class="line"><span>*.nuv=01;35:*.wmv=01;35:*.asf=01;35:*.rm=01;35:*.rmvb=01;35:*.flc=01;35:*.avi=01;35:</span></span>
<span class="line"><span>*.fli=01;35:*.flv=01;35:*.gl=01;35:*.dl=01;35:*.xcf=01;35:*.xwd=01;35:*.yuv=01;35:</span></span>
<span class="line"><span>*.cgm=01;35:*.emf=01;35:*.ogv=01;35:*.ogx=01;35:*.aac=00;36:*.au=00;36:*.flac=00;36:</span></span>
<span class="line"><span>*.m4a=00;36:*.mid=00;36:*.midi=00;36:*.mka=00;36:*.mp3=00;36:*.mpc=00;36:*.ogg=00;36:</span></span>
<span class="line"><span>*.ra=00;36:*.wav=00;36:*.oga=00;36:*.opus=00;36:*.spx=00;36:*.spf=00;36:</span></span>
<span class="line"><span>SSH_CONNECTION=192.168.0.21 34975 192.168.0.11 22</span></span>
<span class="line"><span>LESSCLOSE=/usr/bin/lesspipe %s %s</span></span>
<span class="line"><span>LANG=en_US.UTF-8</span></span>
<span class="line"><span>OLDPWD=/home/shs</span></span>
<span class="line"><span>XDG_SESSION_ID=2253</span></span>
<span class="line"><span>USER=shs</span></span>
<span class="line"><span>PWD=/home/shs</span></span>
<span class="line"><span>HOME=/home/shs</span></span>
<span class="line"><span>SSH_CLIENT=192.168.0.21 34975 22</span></span>
<span class="line"><span>XDG_DATA_DIRS=/usr/local/share:/usr/share:/var/lib/snapd/desktop</span></span>
<span class="line"><span>SSH_TTY=/dev/pts/0</span></span>
<span class="line"><span>MAIL=/var/mail/shs</span></span>
<span class="line"><span>TERM=xterm</span></span>
<span class="line"><span>SHELL=/bin/bash</span></span>
<span class="line"><span>SHLVL=1</span></span>
<span class="line"><span>LOGNAME=shs</span></span>
<span class="line"><span>DBUS_SESSION_BUS_ADDRESS=unix:path=/run/user/1000/bus</span></span>
<span class="line"><span>XDG_RUNTIME_DIR=/run/user/1000</span></span>
<span class="line"><span>PATH=/home/shs/bin:/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin:/usr/games:/usr/local/games:/snap/bin</span></span>
<span class="line"><span>LESSOPEN=| /usr/bin/lesspipe %s</span></span>
<span class="line"><span>_=/usr/bin/env</span></span></code></pre></div>`,12)),e("p",null,[s[1]||(s[1]=a("雖然你可能會看到大量的輸出，上面顯示的第一大部分用於在命令列上使用顏色標識各種文件類型。當你看到類似 ",-1)),s[2]||(s[2]=e("code",null,"*.tar=01;31:",-1)),s[3]||(s[3]=a(" 這樣的東西，這告訴你 ",-1)),s[4]||(s[4]=e("code",null,"tar",-1)),s[5]||(s[5]=a(" 文件將以紅色顯示在文件列表中，然而 ",-1)),s[6]||(s[6]=e("code",null,"*.jpg=01;35:",-1)),s[7]||(s[7]=a(" 告訴你 jpg 文件將以紫色顯現出來。這些顏色旨在使它易於從一個文件列表中分辨出某些文件。你可以在《",-1)),i(n,{href:"https://www.networkworld.com/article/3269587/customizing-your-text-colors-on-the-linux-command-line.html"},{default:p(()=>[...s[0]||(s[0]=[a("在 Linux 命令列中自定義你的顏色",-1)])]),_:1}),s[8]||(s[8]=a("》處學習更多關於這些顏色的定義，和如何自定義它們。",-1))]),s[25]||(s[25]=l(`<p>當你更喜歡一種不加裝飾的顯示時，一種關閉顏色顯示的簡單方法是使用如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l --color=never</span></span></code></pre></div><p>這個命令可以簡單地轉換到一個別名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ alias ll2=&#39;ls -l --color=never&#39;</span></span></code></pre></div><p>你也可以使用 <code>echo</code> 命令來單獨地顯現某個設置。在這個命令中，我們顯示在歷史緩存區中將被記憶命令的數量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo $HISTSIZE</span></span>
<span class="line"><span>1000</span></span></code></pre></div><p>如果你已經移動到某個位置，你在文件系統中的最後位置會被記在這裏：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PWD=/home/shs</span></span>
<span class="line"><span>OLDPWD=/tmp</span></span></code></pre></div><h3 id="作出更改" tabindex="-1">作出更改 <a class="header-anchor" href="#作出更改" aria-label="Permalink to “作出更改”">​</a></h3><p>你可以使用一個像這樣的命令更改環境設置，但是，如果你希望保持這個設置，在你的 <code>~/.bashrc</code> 文件中添加一行代碼，例如 <code>HISTSIZE=1234</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ export HISTSIZE=1234</span></span></code></pre></div><h3 id="export-一個變量的本意是什麼" tabindex="-1">“export” 一個變量的本意是什麼 <a class="header-anchor" href="#export-一個變量的本意是什麼" aria-label="Permalink to ““export” 一個變量的本意是什麼”">​</a></h3><p>導出一個環境變量可使設置用於你的 shell 和可能的子 shell。默認情況下，用户定義的變量是本地的，並不被導出到新的進程，例如，子 shell 和腳本。<code>export</code> 命令使得環境變量可用在子進程中發揮功用。</p><h3 id="添加和移除變量" tabindex="-1">添加和移除變量 <a class="header-anchor" href="#添加和移除變量" aria-label="Permalink to “添加和移除變量”">​</a></h3><p>你可以很容易地在命令列和子 shell 上創建新的變量，並使它們可用。然而，當你登出並再次回來時這些變量將消失，除非你也將它們添加到 <code>~/.bashrc</code> 或一個類似的文件中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ export MSG=&quot;Hello, World!&quot;</span></span></code></pre></div><p>如果你需要，你可以使用 <code>unset</code> 命令來消除一個變量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ unset MSG</span></span></code></pre></div><p>如果變量是局部定義的，你可以通過加載你的啓動文件來簡單地將其設置回來。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo $MSG</span></span>
<span class="line"><span>Hello, World!</span></span>
<span class="line"><span>$ unset $MSG</span></span>
<span class="line"><span>$ echo $MSG</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ . ~/.bashrc</span></span>
<span class="line"><span>$ echo $MSG</span></span>
<span class="line"><span>Hello, World!</span></span></code></pre></div><h3 id="小結" tabindex="-1">小結 <a class="header-anchor" href="#小結" aria-label="Permalink to “小結”">​</a></h3><p>用户賬户是用一組恰當的啓動文件設立的，創建了一個有用的用户環境，而個人用户和系統管理員都可以通過編輯他們的個人設置文件（對於用户）或很多來自設置起源的文件（對於系統管理員）來更改默認設置。</p><hr>`,23)),e("p",null,[s[10]||(s[10]=a("via: ",-1)),i(n,{href:"https://www.networkworld.com/article/3385516/how-to-manage-your-linux-environment.html"},{default:p(()=>[...s[9]||(s[9]=[a("https://www.networkworld.com/article/3385516/how-to-manage-your-linux-environment.html",-1)])]),_:1})]),e("p",null,[s[15]||(s[15]=a("作者：",-1)),i(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:p(()=>[...s[11]||(s[11]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[16]||(s[16]=a(" 選題：",-1)),i(n,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[12]||(s[12]=[a("lujun9972",-1)])]),_:1}),s[17]||(s[17]=a(" 譯者：",-1)),i(n,{href:"https://github.com/robsean"},{default:p(()=>[...s[13]||(s[13]=[a("robsean",-1)])]),_:1}),s[18]||(s[18]=a(" 校對：",-1)),i(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[14]||(s[14]=[a("wxy",-1)])]),_:1})]),e("p",null,[s[21]||(s[21]=a("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[19]||(s[19]=[a("LCTT",-1)])]),_:1}),s[22]||(s[22]=a(" 原創編譯，",-1)),i(n,{href:"https://linux.cn/"},{default:p(()=>[...s[20]||(s[20]=[a("Linux中國",-1)])]),_:1}),s[23]||(s[23]=a(" 榮譽推出",-1))])])}const S=t(h,[["render",g]]);export{v as __pageData,S as default};
